    # stray values in the irregular seed area when determining the palette.
    totals = Counter(grid[r][c] for r in range(3, h) for c in range(3, w)
                     if grid[r][c] != 0)
    if not totals:
        return [row[:] for row in grid]
    max_count = max(totals.values())
    palette = [color for color, count in totals.items()
               if count >= max(3, max_count // 8)]
    period = len(palette)
    if period < 2:
        period = max(2, period)

    out = [row[:] for row in grid]
